	function indParseShift(t) {
		var m2 = indDigits(t).replace(/[–—ـ]/g, "-").match(/(\d{1,2})(?:\s*[:.]\s*(\d{1,2}))?\s*(?:-|الى|إلى|to|→|حتى|ل)\s*(\d{1,2})(?:\s*[:.]\s*(\d{1,2}))?/);
		if (!m2) return null;
		var a = parseInt(m2[1], 10), b = parseInt(m2[3], 10);
		if (m2[2] && parseInt(m2[2], 10) >= 30) a += 1;
		if (m2[4] && parseInt(m2[4], 10) >= 30) b += 1;
		if (a > 24 || b > 24) return null;
		a = a % 24;
		b = b % 24;
		if (a === b) return null;
		return [a, b];
	}
	function indParseShiftList(t) {
		var raw = String(t || "").split(/\n+|،|,|؛|;|\|/);
		var out = [];
		for (var i = 0; i < raw.length; i++) {
			var piece = String(raw[i]).trim();
			if (!piece) continue;
			var sh = indParseShift(piece);
			if (!sh) return null;
			out.push(sh);
		}
		return out.length ? out : null;
	}
	function indShiftHours(sh) {
		return sh[1] > sh[0] ? sh[1] - sh[0] : 24 - sh[0] + sh[1];
	}
