		s += "الحمل الليلي: " + (parseFloat(ind.nkw) || 0) + " kW | تشغيل المحرك: " + ((IND_STARTER[ind.starter] || {}).t || "-") + (parseFloat(ind.bill) > 0 ? " | فاتورة: " + ind.bill + " ريال/شهر" : "") + "\n";
